  <h1>Pendulum Simulator</h1>
  <p>Enter the initial angle (in degrees): <input type="number" id="initial-angle" value="45" /></p>
  <button id="release-button">Release Pendulum</button>
  <canvas id="pendulum-canvas" width="400" height="400"></canvas>

