    let canvas = document.getElementById('pendulum-canvas');
    let ctx = canvas.getContext('2d');
    let pendulumRadius = 20;
    let originX = canvas.width / 2;
    let originY = canvas.height / 2;
    let initialAngle = 0;
    let angle = 0;
    let gravity = 0.98; // adjust this to change the gravitational constant
    let timeStep = 0.02; // adjust this to change the simulation speed
    let pendulumVelocity = 0;
    let released = false;

    function updateAngle() {
      if (released) {
        pendulumVelocity -= gravity * timeStep;
        angle += pendulumVelocity * timeStep;
        pendulumVelocity *= 1 - 0.9 * timeStep; // energy dissipation
        if (Math.abs(pendulumVelocity) < 0.01) {
          pendulumVelocity = 0;
          angle = 0;
          released = false;
        }
      }
    }

    function drawPendulum() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.beginPath();
      ctx.arc(originX, originY, pendulumRadius, 0, 2 * Math.PI);
      ctx.fillStyle = 'black';
      ctx.fill();

      let pendulumEndX = originX + pendulumRadius * Math.sin(angle);
      let pendulumEndY = originY - pendulumRadius * Math.cos(angle);
      ctx.beginPath();
      ctx.moveTo(originX, originY);
      ctx.lineTo(pendulumEndX, pendulumEndY);
      ctx.stroke();
    }

    document.getElementById('release-button').addEventListener('click', () => {
      initialAngle = document.getElementById('initial-angle').value * Math.PI / 180; // convert to radians
      angle = initialAngle;
      pendulumVelocity = 0;
      released = true;
      setInterval(updateAndDraw, timeStep * 1000);
    });

    function updateAndDraw() {
      updateAngle();
      drawPendulum();
    }

    updateAndDraw();
  </script>
</body>
</html>
```

